import {languages,translate} from './i18n.js';
import {emptyTracker,emptyAccount,sampleTracker,validateAccount,attention,orderedAccounts,counts,transition,saveWorkspace,restoreWorkspace,today,validDate,SOURCES} from './tracker.js';
import {searchInstitutions,matchInstitution,institutionById} from './institutions.js';
import {guideFor} from './guides.js';
import {createReader} from './speech.js';
import {sealCase,openCase,download} from './privacy.js';

const $=selector=>document.querySelector(selector);
const main=$('main'),live=$('#live');
const codes=languages.map(([code])=>code);
const initialLanguage=location.pathname.replace(/\/$/,'').slice(1);
let lang=codes.includes(initialLanguage)?initialLanguage:'en',chosen=codes.includes(initialLanguage);
if(chosen)history.replaceState(null,'','/');
let current=emptyTracker(),view='home',selected='',draft=null,step=0,editorMode='new',dirty=false,generation=0;
let pendingDematSource='',pendingEditor=null,unfinished=null,returnView='home',savedFile=false,shareNames=true,shareLocation=true;
let speechRate=.9,voiceChoice={},textLevel=100,dialogOrigin=null,routeMode='online';
const preferencesKey='virasat-reading-settings-v1';
try{const p=JSON.parse(localStorage.getItem(preferencesKey)||'null');if(p){textLevel=[90,100,110,120,130,140,150,160,170,180,190,200].includes(p.textLevel)?p.textLevel:100;speechRate=[.75,.9,1.05].includes(p.speechRate)?p.speechRate:.9;for(const code of codes)if(typeof p.voices?.[code]==='string'&&p.voices[code].length<160)voiceChoice[code]=p.voices[code];for(const [key,cls] of [['contrast','high-contrast'],['motion','no-motion'],['spacing','more-spacing']])document.body.classList.toggle(cls,p[key]===true);document.documentElement.style.fontSize=textLevel+'%';}}catch{}
function rememberReading(){try{localStorage.setItem(preferencesKey,JSON.stringify({textLevel,speechRate,voices:voiceChoice,contrast:document.body.classList.contains('high-contrast'),motion:document.body.classList.contains('no-motion'),spacing:document.body.classList.contains('more-spacing')}));}catch{}}
const deviceKey='virasat-locked-workspace-v1';
let deviceCopy=false;try{deviceCopy=Boolean(localStorage.getItem(deviceKey));}catch{}
const t=key=>translate(lang,key);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy=(key,tag='p',cls='')=>`<${tag} class="${cls}" data-speak>${esc(t(key))}</${tag}>`;
const button=(id,key,cls='secondary',extra='')=>`<button type="button" id="${id}" class="${cls}" ${['found-yes','found-no','found-change','found-unknown','prepare','check-result','submit-request','confirm-record'].includes(id)?'data-speak':''} ${extra}>${key==='back'?'<span aria-hidden="true">‹</span> ':''}${esc(t(key))}${cls==='answer-button'?'<span class="answer-arrow" aria-hidden="true">→</span>':''}</button>`;
const number=n=>new Intl.NumberFormat(lang+'-IN').format(n);
const date=value=>value?new Intl.DateTimeFormat(lang+'-IN',{day:'numeric',month:'short',year:'numeric'}).format(new Date(value+'T12:00:00')):t('neverChecked');
const ownerText=value=>value?.startsWith('@')?t(value.slice(1)):value;
const account=()=>current.accounts.find(a=>a.id===selected);
const accountTitle=a=>a.label||a.institution;
const status=a=>`<span class="status-pill status-${attention(a)}">${esc(t(attention(a)))}</span>`;
const isDue=a=>Boolean(a.followupOn&&a.followupOn<=today()&&!a.linkedDematId);
const taskKey=a=>isDue(a)&&['confirmed','optout'].includes(attention(a))?'recheck':({missing:'prepare',unknown:'helpCheck',review:'helpCheck',change:'prepare',awaiting:'confirmTask',confirmed:a.familyReviewedOn?'summary':'familyRecord',blocked:'requestHelp',optout:'optout',linked:'useDemat'}[attention(a)]);
const icons={bank:'<path d="m3 9 9-5 9 5M4 20h16M6 11v6m6-6v6m6-6v6"/>',demat:'<path d="m3 7 9-4 9 4-9 4-9-4Zm0 5 9 4 9-4M3 17l9 4 9-4"/>',mf:'<path d="M12 3v9h9A9 9 0 0 0 12 3Z"/><path d="M8 4a9 9 0 1 0 12 12"/>',sound:'<path d="m11 5-6 4H2v6h3l6 4V5Zm4 3a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',arrow:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4 10-10"/>'};
const icon=name=>`<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.arrow}</svg>`;
const reader=createReader({onChange:state=>updateSpeech(state)});
function listenBar(){return `<div class="listen-bar" data-no-print><button type="button" id="listen" class="listen-button">${icon('sound')}<span>${t('read')}</span></button><button type="button" id="speech-pause" class="text-button" hidden>${t('pause')}</button><button type="button" id="speech-stop" class="text-button" hidden>${t('stop')}</button><span id="speech-status" class="micro" role="status" aria-live="polite"></span><button type="button" id="speech-help" class="text-button" hidden>${t('voiceSetup')}</button></div><div id="read-along" class="read-along" data-no-print hidden><p class="overline">${t('readingNow')} <span id="speech-position"></span></p><p id="speech-sentence"></p><div class="sentence-controls">${button('speech-previous','previousSentence','text-button')}${button('speech-repeat','repeatSentence','text-button')}${button('speech-next','nextSentence','text-button')}</div></div>`;}
function heading(key,intro='',privateHeading=false){return `<div class="page-heading"><h1 ${privateHeading?'':'data-speak'}>${esc(privateHeading?key:t(key))}</h1>${intro?copy(intro):''}${listenBar()}</div>`;}
function details(key,body,id=''){return `<details ${id?`id="${id}"`:''}><summary data-speak><span>${t(key)}</span></summary><div class="detail-body">${body}</div></details>`;}
function saveNotice(){if(!current.accounts.length&&!unfinished&&!draft&&!pendingEditor)return '';return `<div class="save-notice ${dirty?'is-unsaved':''}" data-no-print><span>${esc(t(dirty?'unsaved':savedFile?'savedStatus':'unsaved'))}</span>${button('save-notice','saveShort','text-button')}</div>`;}
function row(a){return `<button type="button" class="account-row" data-account="${a.id}" aria-label="${esc([accountTitle(a),ownerText(a.owner),t(attention(a))].filter(Boolean).join(', '))}"><span class="account-symbol">${icon(a.type)}</span><span class="account-row-main"><strong>${esc(accountTitle(a))}</strong><span>${[ownerText(a.owner),a.label?a.institution:'',t(a.type),a.last4?'•••• '+a.last4:''].filter(Boolean).map(esc).join(' · ')}</span><span class="row-task">${esc(t(taskKey(a)))}</span></span><span class="account-row-status">${status(a)}${a.followupOn?`<span class="review-due">${a.followupOn<=today()?t('followDue'):t('reviewDate')} · ${date(a.followupOn)}</span>`:''}</span><span class="row-arrow">${icon('arrow')}</span></button>`;}
function home(){
 const c=counts(current),items=orderedAccounts(current.accounts),familyRemaining=items.filter(a=>!a.familyReviewedOn).length,next=items.find(a=>isDue(a)||!['confirmed','optout','linked'].includes(attention(a)))||items.find(a=>a.review==='confirmed'&&!a.familyReviewedOn);
 return `${heading('homeTitle','homeIntro')}${c.total?`${current.synthetic?copy('sample','p','sample-label'):''}<div class="overview-counts"><div><strong>${number(c.total)}</strong><span>${t('accounts')}</span></div><div><strong>${number(current.accounts.filter(a=>isDue(a)||!['confirmed','optout','linked'].includes(attention(a))).length)}</strong><span>${t('needsAttention')}</span></div><div><strong>${number(c.confirmed)}</strong><span>${t('checkedCount')}</span></div></div>${next?`<section class="next-task"><div>${copy('next','p','overline')}<h2>${esc(accountTitle(next))}</h2><p data-speak>${esc(t(taskKey(next)))}</p></div><button type="button" class="primary" data-account="${next.id}">${t('resumeTask')} <span aria-hidden="true">→</span></button></section>`:''}${familyRemaining?`<p class="family-progress">${t('familyRemaining')}: ${number(familyRemaining)}</p>`:''}<div class="home-actions">${button('add',current.synthetic?'startOwnList':'add',next?'secondary':'primary')}${button('summary','summary','text-button')}${button('resume','resume','text-button')}</div>`:`<div class="home-actions">${button('add','startCheck','primary')}${button('resume','resume','text-button')}</div>${copy('startHelp','p','start-help')}<div class="example-types">${['bank','demat','mf'].map(k=>`<span>${icon(k)}${t(k)}</span>`).join('')}</div>${button('demo','example','text-button')}${details('howWorks',copy('howWorksText'))}${details('helpScope',copy('helpScopeText'))}`}${pendingEditor?button('continue-editor','unfinishedChanges','unfinished-link'):''}${unfinished?`<button type="button" id="continue-draft" class="unfinished-link">${t('unfinished')} ${icon('arrow')}</button>`:''}${c.total?`<section class="account-list" aria-label="${t('accounts')}"><div class="list-heading"><h2>${t('accounts')}</h2></div>${items.map(row).join('')}</section>`:''}${saveNotice()}`;
}
function options(name,key,values,description=false){return `<fieldset class="choice-group"><legend data-speak>${t(key)}</legend><div class="${description?'type-options':'choice-options'}">${values.map(([value,label,desc])=>`<label><input aria-describedby="${name}-error" type="radio" name="${name}" value="${value}" ${draft[name]===value?'checked':''}><span>${description?icon(value):''}<span><strong data-speak>${esc(t(label))}</strong>${desc?`<span data-speak>${esc(t(desc))}</span>`:''}</span></span></label>`).join('')}</div><p class="error field-error" id="${name}-error" role="alert"></p></fieldset>`;}
const hints={label:'nicknameExample',owner:'ownerExample',nomineeNote:'nomineeNoteExample',last4:'last4Example',recordNote:'recordNoteExample',recordLocation:'locationHelp'};
function field(name,label,required=false){const hint=hints[name];return `<div class="field"><label for="account-${name}" data-speak>${t(label)}</label><input id="account-${name}" name="${name}" type="text" value="${esc(name==='owner'?ownerText(draft[name]):draft[name])}" maxlength="${name==='last4'?4:['recordLocation','recordNote'].includes(name)?160:80}" ${name==='last4'?'inputmode="numeric"':''} ${required?'required':''} aria-describedby="${hint?`account-${name}-hint `:''}account-${name}-error" autocomplete="off">${hint?`<p class="help" id="account-${name}-hint" data-speak>${t(hint)}</p>`:''}<p id="account-${name}-error" class="error field-error" role="alert"></p></div>`;}
function institutionField(){const key={bank:'searchBank',demat:'searchDemat',mf:'searchMf'}[draft.type];return `<div class="institution-picker field"><label for="account-institution" data-speak>${t(key)}</label><div class="combobox-anchor"><input id="account-institution" name="institution" type="text" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="institution-results" aria-describedby="institution-help account-institution-error" value="${esc(draft.institution)}" autocomplete="off" autocapitalize="words" spellcheck="false" maxlength="80" required><div id="institution-results" role="listbox" aria-label="${t('suggestions')}" hidden></div></div><p id="institution-announcement" class="sr-only" role="status" aria-live="polite"></p><p class="help" id="institution-help" data-speak>${t('searchHelp')}</p><p id="account-institution-error" class="error field-error" role="alert"></p></div>${copy(draft.type+'Location','p','context-guide')}`;}
function contextFields(){return `${options('owner','whose',[['@me','me'],['@parent','parent'],['@familyMember','familyMember'],['','unknown']])}${options('holding','holderQuestion',[['sole','sole'],['joint','joint'],['unknown','unknown']])}${draft.type==='bank'?options('product','bankProduct',[['savings','savings'],['deposit','deposit'],['unknown','unknown']]):draft.type==='mf'?`${options('mfMode','mfMode',[['folio','folioMode'],['demat','dematMode'],['unknown','unknown']])}${details('identifyHelp',copy('identifyText'))}`:''}`;}
function nomineeChoices(){return `${copy('nomineeExplain','p','nominee-explanation')}${options('nomination','nomination',[['unknown','unknown'],['registered','nomineeYes'],['missing','nomineeNo'],['change','change']])}${details('optout',`${copy('optoutHelp')}<label class="check-field"><input type="checkbox" id="choose-optout" ${draft.nomination==='optout'?'checked':''}><span>${t('optout')}</span></label>`)}`;}
function accountForm(){const editing=editorMode==='edit';return `${editing?button('cancel-edit','back','back-button'):''}${!editing?`<p class="step-label">${t('step')} ${number(step+1)} ${t('of')} ${number(4)} · ${t(['stepType','stepInstitution','stepContext','stepNomination'][step])}</p><div class="step-track" aria-hidden="true">${[0,1,2,3].map(i=>`<span class="${i<=step?'reached':''}"></span>`).join('')}</div>`:''}${heading(editing?'edit':['typeQuestion','institutionQuestion','accountContext','nomination'][step],!editing&&step===2?'contextHelp':'')}<form novalidate id="account-form" class="form-flow">${editing?`${institutionField()}${contextFields()}`:step===0?`${options('type','type',[['bank','bank','bankDescription'],['demat','demat','dematDescription'],['mf','mf','mfDescription']],true)}${details('identifyHelp',copy('dematDescription')+copy('bankDescription')+copy('mfDescription'))}`:step===1?institutionField():step===2?contextFields():nomineeChoices()}<p id="form-error" class="error" role="alert"></p><div class="button-row">${button('form-back','back','back-button')}<button type="submit" class="primary">${t(editing?'update':step===3?'seeNext':'continue')}</button></div></form>${saveNotice()}`;}
function sourceDisclosure(a){const guide=guideFor(a);return details('source',`${copy(guide.scope,'p','help')}<a href="${guide.url}" target="_blank" rel="noopener noreferrer">${t(guide.label)} ↗</a><p class="micro">${t('checkedOn')}: ${date(guide.reviewedOn)}</p>${copy('sourceNote','p','micro')}${copy('selfReport','p','micro')}`);}
function instructionList(keys){return `<ol class="task-checklist" role="list">${keys.map((key,i)=>`<li><span class="step-number" aria-hidden="true">${number(i+1)}</span>${copy(key)}</li>`).join('')}</ol>`;}
function evidenceExample(){return details('seeEvidence',`${copy('fictionalExample','p','micro')}<div class="evidence-examples"><div>${copy('submitted','h3')}${copy('receiptExample')}</div><div>${copy('confirmed','h3')}${copy('registeredExample')}</div></div>`);}
function officialLink(a){const guide=guideFor(a);return `<a class="official-link" href="${guide.url}" target="_blank" rel="noopener noreferrer">${t([SOURCES.bank,SOURCES.sebi].includes(guide.url)?'readRules':'openOfficial')} <span aria-hidden="true">↗</span></a>`;}
function detail(){
 const a=account(),state=attention(a),guide=guideFor(a);
 let content='',actions='';
 if(['unknown','review'].includes(state)) {content=instructionList(guide.check);actions=button('check-result','whatFound','primary')+button('submit-request','markSubmitted','text-button');}
 if(['missing','change'].includes(state)){content=copy(state==='change'?'foundChange':'foundNo')+copy('prepareIntro');actions=button('prepare','prepare','primary')+button('check-result','helpCheck','text-button')+button('submit-request','markSubmitted','text-button');}
 if(state==='awaiting'){content=instructionList(['followRequest','confirmRegistration','waitRegistration']);actions=button('confirm-record','markConfirmed','primary')+button('blocked','requestHelp','text-button');}
 if(state==='blocked'){content=copy('blockedHelp');actions=button('prepare','prepare','primary')+button('check-result','whatFound','text-button');}
 if(state==='confirmed'){content=copy(a.familyReviewedOn?'familyReadyNext':'familyReviewHelp')+`<p>${esc(t(a.evidenceScope==='details'?'detailsChecked':'statusOnly'))}</p>`;actions=(isDue(a)?button('recheck','recheck','primary')+button('family','familyRecord','text-button'):(a.familyReviewedOn?button('summary','summary','primary')+button('family','familyRecord','text-button'):button('family','familyRecord','primary'))+button('recheck','recheck','text-button'))+button('change-nomination','foundChange','text-button');}
 if(state==='linked'){content=copy('mfDematHelp')+`<p>${t('linkedTo')} <bdi>${esc(accountTitle(current.accounts.find(d=>d.id===a.linkedDematId)))}</bdi></p>`;actions=button('use-demat','useDemat','primary');}
 if(state==='optout'){content=copy('optoutHelp');actions=button('recheck','recheck','primary');}
 if(a.type==='mf'&&a.mfMode==='demat'&&!['confirmed','awaiting','optout','linked'].includes(state)){content=copy('mfDematHelp');actions=button('use-demat','useDemat','primary');}
 return `${button('back-list','back','back-button')}${heading(accountTitle(a),'',true)}<p class="account-subtitle">${[t(a.type),ownerText(a.owner),a.label?a.institution:'',a.last4?'•••• '+a.last4:''].filter(Boolean).map(esc).join(' · ')}</p><div class="detail-grid"><section class="task-card"><div class="section-heading">${copy('next','p','overline')}${status(a)}</div>${copy(taskKey(a),'h2')}${!guide.specific&&['unknown','review','missing','change'].includes(state)?copy('routeFallback','p','help'):''}${content}<div class="button-row">${actions}</div>${state==='unknown'||state==='review'?officialLink(a):''}${['unknown','review','awaiting','blocked'].includes(state)?details('askHelp',copy('askText')+button('copy-question','copyQuestion','text-button')):''}${['awaiting','confirmed'].includes(state)?evidenceExample():''}${sourceDisclosure(a)}</section><aside class="progress-card"><h2>${t('currentRecord')}</h2>${copy('selfReport','p','micro')}<dl class="record-facts"><dt>${t('nomination')}</dt><dd>${t(a.linkedDematId?'linked':a.nomination)}</dd><dt>${t('checkedOn')}</dt><dd>${date(a.checkedOn)}</dd>${a.submittedOn?`<dt>${t('submissionDate')}</dt><dd>${date(a.submittedOn)}</dd>`:''}${a.confirmationOn?`<dt>${t('confirmationDate')}</dt><dd>${date(a.confirmationOn)}</dd>`:''}${a.followupOn?`<dt>${t('reviewDate')}</dt><dd>${date(a.followupOn)}${a.followupOn<=today()?` · ${t('followDue')}`:''}</dd>`:''}</dl>${button('followup','followup','text-button')}${a.followupOn?button('calendar','calendar','text-button'):''}${details('familyRecord',`${copy(a.familyReviewedOn?'familyReviewed':'familyPending','p','family-status')}<p>${t('owner')}: <bdi>${esc(ownerText(a.owner)||t('notProvided'))}</bdi></p><p>${t('nominees')}: <bdi>${esc([...a.nominees,a.nomineeNote].filter(Boolean).join(', ')||t('notProvided'))}</bdi></p><p>${t('recordLocation')}: <bdi>${esc(a.recordLocation||t('notProvided'))}</bdi></p>${button('family-aside','edit','text-button')}`)}${a.recordNote?details('privateRecord',`<p><bdi>${esc(a.recordNote)}</bdi></p>${copy('privateRecordHelp','p','micro')}`):''}${a.events.length?details('history',`<ol class="event-list">${a.events.slice().reverse().map(e=>`<li>${t(e.kind)} <span>${date(e.on)}</span></li>`).join('')}</ol>`):''}<div class="record-actions">${button('edit-account','edit','text-button')}${button('remove-account','remove','text-button danger')}</div></aside></div>${saveNotice()}`;
}
function checkResult(){return `${button('back-detail','back','back-button')}${heading('whatFound','checkFirst')}<div class="answer-list">${[['found-yes','foundYes'],['found-no','foundNo'],['found-change','foundChange'],['found-unknown','foundUnknown']].map(([id,key])=>button(id,key,'answer-button')).join('')}</div>${details('optout',copy('optoutHelp')+button('found-optout','optout','text-button'))}${evidenceExample()}`;}
function prepare(){const a=account(),guide=guideFor(a),offline=routeMode==='offline'||a.holding==='joint';return `${button('back-detail','back','back-button')}${heading('prepare','prepareIntro')}<fieldset class="route-choice"><legend data-speak>${t('routeChoice')}</legend><div class="button-row">${button('route-online','onlineRoute',offline?'secondary':'primary',`aria-pressed="${!offline}" ${a.holding==='joint'?'disabled':''}`)}${button('route-offline','offlineRoute',offline?'primary':'secondary',`aria-pressed="${offline}"`)}</div></fieldset><div class="guide-layout"><section>${copy('haveReady','h2')}${instructionList(['prepareNames','prepareMinor','prepareAccess'])}${details('offlineHelp',copy('offlineText'))}${details('askHelp',copy('askText')+button('copy-question','copyQuestion','text-button'))}</section><section class="institution-route">${copy('whatToDo','h2')}${copy(guide.scope,'p','help')}${instructionList(offline?guide.offline:guide.action)}${dirty?`<div class="handoff-save">${copy('saveBeforeLeaving','p','help')}${button('route-save','saveShort','text-button')}</div>`:''}${officialLink(a)}${evidenceExample()}<div class="button-row">${button('submit-request','markSubmitted','primary')}</div>${sourceDisclosure(a)}</section></div>${saveNotice()}`;}
function dateParts(name){if(!draft._dateParts)draft._dateParts={};if(!draft._dateParts[name]){const [year='',month='',day='']=(draft[name]||'').split('-');draft._dateParts[name]={day,month,year};}return draft._dateParts[name];}
function dateField(name,key){const parts=dateParts(name);return `<fieldset class="date-field"><legend data-speak>${t(key)}</legend><div class="date-parts">${['day','month','year'].map(part=>`<div><label for="account-${name}-${part}">${t(part)}</label><input id="account-${name}-${part}" data-date-name="${name}" data-date-part="${part}" type="text" inputmode="numeric" maxlength="${part==='year'?4:2}" value="${esc(parts[part])}" placeholder="${part==='day'?'14':part==='month'?'09':'2026'}" aria-describedby="account-${name}-hint account-${name}-error"></div>`).join('')}</div><p class="help" id="account-${name}-hint" data-speak>${t(name==='followupOn'?'followupHelp':name==='submittedOn'?'submissionExample':'dateExample')}</p><p id="account-${name}-error" class="error field-error" role="alert"></p></fieldset>`;}
function recordChoices(){return `<fieldset class="record-options"><legend data-speak>${t('recordKind')}</legend>${['statement','registration'].map(k=>`<label><input id="record-${k}" name="recordKind" type="radio" value="${k}" ${draft.recordKind===k?'checked':''} aria-describedby="record-${k}-hint account-recordKind-error"><span><strong data-speak>${t(k)}</strong><span data-speak id="record-${k}-hint">${t(k+'Example')}</span></span></label>`).join('')}<p id="account-recordKind-error" class="error field-error" role="alert"></p></fieldset>`;}
function progressForm(){const confirm=view==='confirm',follow=view==='followup';return `${button('back-detail','back','back-button')}${heading(follow?'followup':confirm?'markConfirmed':'markSubmitted',follow?'':confirm?'confirmationRequired':'receiptGuide')}<form novalidate id="progress-form" class="narrow-card">${confirm?`${recordChoices()}${options('evidenceScope','evidenceScope',[['status','statusOnly'],['details','detailsChecked']])}`:''}${dateField(follow?'followupOn':confirm?'confirmationOn':'submittedOn',follow?'reviewDate':confirm?'confirmationDate':'submissionDate')}${!follow?field('recordNote','recordNote'):''}${confirm?`<label class="check-field"><input id="account-confirmationChecked" name="confirmationChecked" type="checkbox" ${draft.confirmationChecked?'checked':''} aria-describedby="account-confirmationChecked-error"><span data-speak>${t('confirmationCheck')}</span></label><p id="account-confirmationChecked-error" class="error field-error" role="alert"></p>`:''}<p id="form-error" class="error" role="alert"></p><div class="button-row">${button('cancel-progress','back','back-button')}<button type="submit" class="primary">${t('update')}</button></div></form>${confirm?evidenceExample():''}${saveNotice()}`;}
function familyForm(){return `${button('back-detail','back','back-button')}${heading('familyRecord','familyHelp')}<form novalidate id="family-form" class="form-flow">${field('owner','owner')}${field('label','nickname')}${field('last4','last4')}<fieldset class="nominee-records"><legend data-speak>${t('nominees')}</legend>${copy('optionalDetails','p','help')}<div id="nominee-inputs">${(draft.nominees.length?draft.nominees:['']).map((value,i)=>`<div class="nominee-line"><label for="nominee-${i}">${t('nomineeNote')} ${number(i+1)}</label><input type="text" id="nominee-${i}" data-nominee="${i}" value="${esc(value)}" maxlength="80" autocomplete="off">${i?`<button type="button" data-remove-nominee="${i}" aria-label="${t('removeNote')} ${number(i+1)}">×</button>`:''}</div>`).join('')}</div>${draft.nominees.length<(draft.type==='bank'?4:3)?button('add-nominee','addNomineeNote','text-button'):''}${draft.nomineeNote?field('nomineeNote','nomineeNote'):''}</fieldset>${field('recordLocation','recordLocation')}<div class="family-review">${copy('familyReviewHelp','p','help')}<label class="check-field"><input id="reviewed-family" type="checkbox" ${draft.familyReviewedOn?'checked':''}><span data-speak>${t('familyReviewCheck')}</span></label></div><p id="form-error" class="error" role="alert"></p><div class="button-row">${button('cancel-family','back','back-button')}<button type="submit" class="primary">${t('update')}</button></div></form>${saveNotice()}`;}
function sheetBody(){return `${current.synthetic?copy('sample','p','sample-label'):''}${orderedAccounts(current.accounts).map(a=>`<article class="summary-account"><div class="summary-top"><h2>${esc(accountTitle(a))}</h2>${status(a)}</div><p>${esc(t(a.type))}${a.label?' · '+esc(a.institution):''}${a.last4?' · •••• '+a.last4:''}</p>${a.linkedDematId?`<p>${t('linkedTo')}: ${esc(accountTitle(current.accounts.find(d=>d.id===a.linkedDematId)))}</p>`:''}${shareNames?`<p>${t('whose')} <bdi>${esc(ownerText(a.owner)||t('notProvided'))}</bdi></p><p>${t('nominees')}: <bdi>${esc([...a.nominees,a.nomineeNote].filter(Boolean).join(', ')||t(a.familyReviewedOn?'notIncluded':'notProvided'))}</bdi></p>`:''}<p class="family-status">${t(a.familyReviewedOn?'familyReviewed':'familyPending')}${a.familyReviewedOn?' · '+date(a.familyReviewedOn):''}</p><p><strong>${t('next')}:</strong> ${t(a.review==='confirmed'&&a.familyReviewedOn?'familyReadyNext':taskKey(a))}</p><p>${t('checkedOn')}: ${date(a.checkedOn)}${a.review==='confirmed'?' · '+t(a.evidenceScope==='details'?'detailsChecked':'statusOnly'):''}</p>${a.submittedOn?`<p>${t('submissionDate')}: ${date(a.submittedOn)}</p>`:''}${a.confirmationOn?`<p>${t('confirmationDate')}: ${date(a.confirmationOn)}</p>`:''}${a.followupOn?`<p>${t('reviewDate')}: ${date(a.followupOn)}</p>`:''}${shareLocation&&a.recordLocation?`<p>${t('recordLocation')} <bdi>${esc(a.recordLocation)}</bdi></p>`:''}<a href="${guideFor(a).url}" target="_blank" rel="noopener noreferrer">${t('openOfficial')}</a></article>`).join('')}<p class="micro">${t('selfReport')}</p><p class="micro">${t('noIds')}</p><p class="micro">${t('boundary')}</p>`;}
function summary(){return `${button('back-list','back','back-button')}${heading('summary','shareHelp')}<div class="share-controls" data-no-print><label class="check-field"><input id="share-names" type="checkbox" ${shareNames?'checked':''}><span>${t('shareNames')}</span></label><label class="check-field"><input id="share-location" type="checkbox" ${shareLocation?'checked':''}><span>${t('shareLocation')}</span></label></div><section id="family-sheet" class="summary-card">${sheetBody()}</section><div class="button-row" data-no-print>${button('print','print','primary')}${button('export','export','secondary')}${button('save-sheet','saveShort','text-button')}</div>`;}
function vault(){const saving=view==='save';return `${button('back-vault','back','back-button')}${heading(saving?'save':'resume',saving?'saveIntro':'saveTip')}<form novalidate id="vault-form" class="narrow-card">${!saving?`<div class="field"><label for="saved-file" data-speak>${t('savedFile')}</label><input id="saved-file" type="file" accept=".virasat" aria-describedby="saved-file-error"><p id="saved-file-error" class="error field-error" role="alert"></p></div>${deviceCopy?`<label class="check-field"><input type="checkbox" id="use-device"><span>${t('openDevice')}</span></label>`:''}`:''}<div class="field"><label for="password" data-speak>${t('password')}</label><input id="password" type="password" minlength="12" maxlength="256" required autocomplete="${saving?'new-password':'current-password'}" aria-describedby="password-help password-error"><p class="help" id="password-help" data-speak>${t('passwordHelp')}</p><p id="password-error" class="error field-error" role="alert"></p></div>${saving?`<div class="field"><label for="password-repeat">${t('passwordAgain')}</label><input id="password-repeat" type="password" minlength="12" maxlength="256" required autocomplete="new-password" aria-describedby="password-repeat-error"><p id="password-repeat-error" class="error field-error" role="alert"></p></div>`:''}<label class="check-field"><input id="show-password" type="checkbox"><span>${t('showPassword')}</span></label>${saving?`<label class="check-field"><input id="keep-device" type="checkbox" ${deviceCopy?'checked':''}><span data-speak>${t('keepDevice')}</span></label>${copy('deviceHelp','p','help')}`:''}${copy('privacyDetail','p','help')}<p id="vault-status" role="status" aria-live="polite"></p><div class="button-row"><button type="submit" class="primary">${t(saving?'save':'resume')}</button></div>${deviceCopy?button('forget-device','forgetDevice','text-button danger'):''}</form>`;}

function announce(key){live.textContent='';requestAnimationFrame(()=>{live.textContent=t(key);});}
function markDirty(){dirty=true;generation++;const notice=$('.save-notice');if(notice){notice.classList.add('is-unsaved');notice.querySelector('span').textContent=t('unsaved');}}
function storeAccount(value){const a=validateAccount(value);const candidates=current.accounts.filter(x=>x.id!==a.id).concat(a);for(const item of candidates)if(item.linkedDematId&&!candidates.some(d=>d.id===item.linkedDematId&&d.type==='demat'))throw new Error('invalidSave');const index=current.accounts.findIndex(x=>x.id===a.id);if(index<0)current.accounts.push(a);else current.accounts[index]=a;selected=a.id;if(unfinished?.sourceId===a.id&&(a.type!=='mf'||a.mfMode!=='demat'||a.linkedDematId))unfinished.sourceId='';markDirty();if(view==='form'&&editorMode==='new'){unfinished=null;if(pendingDematSource&&a.type==='demat'){const sourceId=pendingDematSource;pendingDematSource='';queueMicrotask(()=>confirmDematLink(sourceId,a.id));}}if(pendingEditor?.account.id===a.id)pendingEditor=null;draft=null;view='detail';draw();announce('updated');}
function keepDraft(){if(!draft)return;if(view==='form'&&editorMode==='new')unfinished={account:structuredClone(draft),step,sourceId:pendingDematSource};else if(['form','family','confirm','submit','followup'].includes(view))pendingEditor={view,mode:editorMode,step,account:structuredClone(draft)};}
function go(next){generation++;reader.stop();keepDraft();draft=null;view=next;draw();}
function begin(){generation++;if(current.accounts.length>=50){announce('accountLimit');return false;}pendingDematSource='';unfinished=null;draft={...emptyAccount(),type:''};step=0;editorMode='new';view='form';markDirty();draw();return true;}
function openEditor(next){
 if(pendingEditor){if(pendingEditor.view===next&&pendingEditor.account.id===selected){draft=structuredClone(pendingEditor.account);step=pendingEditor.step;editorMode=pendingEditor.mode;view=next;draw();return;}confirmAction('replaceChanges',()=>{pendingEditor=null;openEditor(next);});return;}
 generation++;draft=structuredClone(account());editorMode='edit';if(next==='confirm'){draft.recordKind='';draft.confirmationChecked=false;draft.confirmationOn='';}view=next;draw();
}
function openProgress(next){openEditor(next);}

function pageDirection(){document.documentElement.lang=lang;document.documentElement.dir='ltr';document.body.classList.toggle('urdu',lang==='ur');document.querySelectorAll('[data-speak], h1, h2, h3, label, legend, summary, .help, .error, .account-row-main, .status-pill, .record-facts, .language-tiles strong').forEach(el=>{el.dir=lang==='ur'?'rtl':'ltr';});}
function draw(focus=true){
 reader.stop();document.body.classList.toggle('language-gate',!chosen);$('.site-header').hidden=!chosen;$('footer').hidden=!chosen;$('.skip').hidden=!chosen;
 if(!chosen){main.className='';main.innerHTML=`<section class="language-picker"><div class="gate-brand">${$('.brand').innerHTML}</div><h1>Choose your language</h1><div class="language-tiles">${languages.map(([code,label])=>`<button type="button" data-language="${code}" lang="${code}"><strong dir="${code==='ur'?'rtl':'ltr'}">${label}</strong></button>`).join('')}</div></section>`;return;}
 main.className='app-shell';$('#language-button').textContent=languages.find(([c])=>c===lang)[1];$('#language-button').setAttribute('aria-label',t('language')+': '+languages.find(([c])=>c===lang)[1]);$('#access-toggle').setAttribute('aria-label',t('readingSettings'));$('#home-button').setAttribute('aria-label',t('home'));$('#help').textContent=t('privacyHelp');$('#clear').textContent=t('clear');$('.skip').textContent=t('skip');
 if(['detail','check','prepare','confirm','submit','family','followup'].includes(view)&&!account()){view='home';draft=null;}
 main.innerHTML=(current.synthetic&&!['home','summary'].includes(view)?copy('sample','p','sample-label'):'')+({home,form:accountForm,detail,check:checkResult,prepare,confirm:progressForm,submit:progressForm,followup:progressForm,family:familyForm,summary,save:vault,resume:vault}[view]||home)();pageDirection();
 if($('#account-institution'))bindInstitution();
 if(focus){main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
}
function showError(id,key){const el=document.getElementById(id);if(el)el.textContent=t(key);}
function clearErrors(){main.querySelectorAll('.error').forEach(e=>e.textContent='');main.querySelectorAll('[aria-invalid]').forEach(e=>e.removeAttribute('aria-invalid'));}
function invalid(name,key){showError(document.getElementById('account-'+name+'-error')?'account-'+name+'-error':name+'-error',key);const input=$('#account-'+name)||$(`[data-date-name="${name}"]`)||$(`[name="${name}"]`);if(input){input.setAttribute('aria-invalid','true');input.focus();}else showError('form-error',key);}
function normaliseDigits(text){return text.replace(/[०-९০-৯٠-٩۰-۹]/g,c=>String(c.charCodeAt(0)-(c>='०'&&c<='९'?0x966:c>='০'&&c<='৯'?0x9e6:c>='٠'&&c<='٩'?0x660:0x6f0)));}
function readDates(){for(const [name,parts] of Object.entries(draft?._dateParts||{})){const {year,month,day}=parts;draft[name]=[year,month,day].every(v=>v==='')?'':`${year.padStart(4,'0')}-${month.padStart(2,'0')}-${day.padStart(2,'0')}`;}}
function bindInstitution(){
 const input=$('#account-institution'),list=$('#institution-results');let results=[],active=-1;
 const close=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');active=-1;};
 const render=()=>{results=searchInstitutions(draft.type,input.value,8);active=-1;list.innerHTML=results.map((r,i)=>`<div role="option" id="institution-option-${i}" aria-selected="false" data-institution-index="${i}"><span>${esc(r.name)}</span><span aria-hidden="true">↵</span></div>`).join('')+(input.value.trim()?`<div role="option" id="institution-option-${results.length}" aria-selected="false" data-institution-index="${results.length}" class="custom-institution">${esc(t('useTyped'))}: <strong>${esc(input.value.trim())}</strong></div>`:'');if(!results.length&&!input.value.trim()){close();return;}list.hidden=false;input.setAttribute('aria-expanded','true');input.removeAttribute('aria-activedescendant');$('#institution-announcement').textContent=results.length?`${number(results.length)} ${t('suggestions')}`:t('noMatches');};
 const choose=i=>{const item=results[i];draft.institution=item?.name||input.value.trim();draft.institutionId=item?.id||'';input.value=draft.institution;markDirty();close();input.focus();};
 input.addEventListener('focus',render);input.addEventListener('input',()=>{draft.institution=input.value;draft.institutionId='';render();});
 input.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close();return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(list.hidden)render();const count=list.children.length;if(!count)return;active=(active+(e.key==='ArrowDown'?1:-1)+count)%count;[...list.children].forEach((el,i)=>el.setAttribute('aria-selected',String(i===active)));input.setAttribute('aria-activedescendant',list.children[active].id);list.children[active].scrollIntoView({block:'nearest'});}else if(e.key==='Enter'&&!list.hidden&&active>=0){e.preventDefault();choose(active);}else if(e.key==='Tab')close();});
 list.addEventListener('pointerdown',e=>e.preventDefault());list.addEventListener('click',e=>{const option=e.target.closest('[data-institution-index]');if(option)choose(Number(option.dataset.institutionIndex));});input.addEventListener('blur',close);
}
function updateSpeech({state,error,index,total,text,source}){
 const active=['playing','paused'].includes(state),pause=$('#speech-pause'),stop=$('#speech-stop'),status=$('#speech-status');
 if(pause){pause.hidden=!active;pause.textContent=t(state==='paused'?'resumeAudio':'pause');}if(stop)stop.hidden=!active;
 const message=t(({playing:'listening',paused:'pause',finished:'finishedAudio',error:'speechError',unavailable:'speechUnavailable'})[state]||'')||'';
 if(status&&status.textContent!==message)status.textContent=message;
 if(!active&&/^speech-(pause|stop|previous|repeat|next)$/.test(document.activeElement?.id||''))$('#listen')?.focus();
 if($('#speech-help'))$('#speech-help').hidden=!['error','unavailable'].includes(state);
 main.querySelectorAll('.reading-current').forEach(el=>el.classList.remove('reading-current'));
 if(active&&source!==null)main.querySelector(`[data-reading-source="${source}"]`)?.classList.add('reading-current');
 if($('#read-along')){$('#read-along').hidden=!active;$('#speech-sentence').textContent=text||'';$('#speech-position').textContent=active?`${number(index+1)} ${t('of')} ${number(total)}`:'';$('#speech-previous').disabled=index===0;$('#speech-next').disabled=index>=total-1;}
 const preview=$('#voice-status');if(preview)preview.textContent=state==='unavailable'?t('speechUnavailable'):error?t('speechError'):active?t('listening'):state==='finished'?t('finishedAudio'):'';
}
function readPage(){
 const blocks=[...main.querySelectorAll('[data-speak]')].filter(e=>e.checkVisibility({checkVisibilityCSS:true})&&!e.parentElement.closest('[data-speak]')).map((e,i)=>{e.dataset.readingSource=String(i);return {text:e.textContent.trim(),source:i};});
 reader.start(blocks,{language:lang,voice:reader.voices(lang).find(v=>v.name===voiceChoice[lang]),rate:speechRate});
}
function voiceHelp(){return `${copy('voiceSetupHelp','p','help')}${details('voiceSetup',`${copy('androidVoice')}<a href="https://support.google.com/accessibility/android/answer/6006983" target="_blank" rel="noopener noreferrer">Android ↗</a>${copy('appleVoice')}<a href="https://support.apple.com/guide/mac-help/mchlp2290/mac" target="_blank" rel="noopener noreferrer">Mac ↗</a> · <a href="https://support.apple.com/en-sg/guide/iphone/iph96b214f0/ios" target="_blank" rel="noopener noreferrer">iPhone ↗</a>${copy('voiceFallback')}`)}${button('refresh-voices','refreshVoices','text-button')}`;}
function dialogHead(id,key){return `<div class="dialog-head"><h2 id="${id}">${t(key)}</h2><button type="button" class="dialog-close" data-close aria-label="${t('close')}">×</button></div>`;}
function openDialog(id,body){reader.stop();dialogOrigin=document.activeElement;const dialog=$('#'+id);dialog.innerHTML=body;pageDirection();dialog.showModal();dialog.querySelector('[data-close]')?.addEventListener('click',()=>dialog.close());return dialog;}
function confirmAction(key,action){const d=openDialog('confirm-dialog',`${dialogHead('confirm-title','beforeContinue')}${copy(key)}<div class="button-row">${button('confirm-cancel','cancel')}${button('confirm-action','continue','primary')}</div>`);$('#confirm-cancel').onclick=()=>d.close();$('#confirm-action').onclick=()=>{d.close();action();};$('#confirm-cancel').focus();}
function languageDialog(){const d=openDialog('language-dialog',`${dialogHead('language-title','language')}${copy('languageHelp')}<div class="language-tiles">${languages.map(([code,label])=>`<button type="button" data-language="${code}" lang="${code}" aria-pressed="${code===lang}"><strong dir="${code==='ur'?'rtl':'ltr'}">${label}</strong></button>`).join('')}</div>`);d.onclick=e=>{const b=e.target.closest('[data-language]');if(b){lang=b.dataset.language;d.close();draw(false);}};}
function accessDialog(){
 const voices=reader.voices(lang),contrast=document.body.classList.contains('high-contrast'),motion=document.body.classList.contains('no-motion'),spacing=document.body.classList.contains('more-spacing');
 const d=openDialog('access-dialog',`${dialogHead('access-title','readingSettings')}<section class="settings-section"><h3>${t('appearance')}</h3><div class="size-control"><span>${t('textSize')}</span><button id="smaller" aria-label="${t('smaller')}">A−</button><output id="text-size">${textLevel}%</output><button id="larger" aria-label="${t('larger')}">A+</button></div>${[['contrast',contrast],['motion',motion],['lineSpacing',spacing]].map(([k,on])=>`<label class="setting-switch"><span>${t(k)}</span><input id="setting-${k}" role="switch" type="checkbox" ${on?'checked':''}></label>`).join('')}</section><section class="settings-section"><h3>${t('voice')}</h3>${copy('voiceHelp','p','help')}${voices.length?`<p id="selected-voice" class="selected-voice">${esc((voices.find(v=>v.name===voiceChoice[lang])||voices[0]).name)} <span class="micro" dir="ltr">${esc((voices.find(v=>v.name===voiceChoice[lang])||voices[0]).lang)}</span></p>${details('chooseVoice',`<fieldset class="voice-list"><legend class="sr-only">${t('voice')}</legend>${voices.map((v,i)=>`<label class="check-field"><input type="radio" name="voice" value="${esc(v.name)}" ${(voiceChoice[lang]?voiceChoice[lang]===v.name:i===0)?'checked':''}><span>${esc(v.name)} <span class="micro" dir="ltr">${esc(v.lang)}</span></span></label>`).join('')}</fieldset>`)} `:copy('speechUnavailable','p','help')}<fieldset class="speed-control"><legend>${t('speed')}</legend>${[[.75,'slower'],[.9,'normalSpeed'],[1.05,'faster']].map(([rate,k])=>`<label><input name="speed" type="radio" value="${rate}" ${speechRate===rate?'checked':''}><span>${t(k)}</span></label>`).join('')}</fieldset>${button('preview-voice','previewVoice','text-button',voices.length?'':'disabled')}${voiceHelp()}<p id="voice-status" role="status" class="help"></p></section>${copy('readingPreferences','p','help')}${button('reset-settings','resetSettings','text-button')}`);
 function size(amount){textLevel=Math.max(90,Math.min(200,textLevel+amount));document.documentElement.style.fontSize=textLevel+'%';$('#text-size').textContent=textLevel+'%';$('#smaller').disabled=textLevel<=90;$('#larger').disabled=textLevel>=200;rememberReading();}
 $('#smaller').onclick=()=>size(-10);$('#larger').onclick=()=>size(10);size(0);
 for(const [key,cls] of [['contrast','high-contrast'],['motion','no-motion'],['lineSpacing','more-spacing']])$('#setting-'+key).onchange=e=>{document.body.classList.toggle(cls,e.target.checked);rememberReading();};
 d.querySelectorAll('[name=voice]').forEach(el=>el.onchange=()=>{voiceChoice[lang]=el.value;rememberReading();$('#selected-voice').textContent=el.value+' · '+voices.find(v=>v.name===el.value).lang;reader.stop();});d.querySelectorAll('[name=speed]').forEach(el=>el.onchange=()=>{speechRate=Number(el.value);rememberReading();reader.stop();});
 $('#preview-voice').onclick=()=>reader.start(t('voicePreview'),{language:lang,voice:voices.find(v=>v.name===voiceChoice[lang]),rate:speechRate});$('#reset-settings').onclick=()=>{textLevel=100;size(0);speechRate=.9;voiceChoice={};document.body.classList.remove('high-contrast','no-motion','more-spacing');try{localStorage.removeItem(preferencesKey);}catch{}d.close();accessDialog();};
 $('#refresh-voices').onclick=()=>{d.close();accessDialog();};
}
function helpDialog(){openDialog('help-dialog',`${dialogHead('help-title','privacyHelp')}${copy('howWorksText')}${copy('noIds')}${copy('privacyDetail')}${copy('deviceHelp')}${copy('voiceHelp')}${copy('boundary')}${copy('translationNotice')}`);}
function beginLinkedDemat(sourceId){const start=()=>{if(!begin())return;pendingDematSource=sourceId;draft.type='demat';step=1;draw();};unfinished?confirmAction('replaceDraft',start):start();}
function confirmDematLink(sourceId,targetId){const source=current.accounts.find(a=>a.id===sourceId),target=current.accounts.find(a=>a.id===targetId);if(!source||!target)return;const d=openDialog('confirm-dialog',`${dialogHead('confirm-title','checkConnection')}${copy('connectionHelp')}<p><bdi>${esc(accountTitle(source))} · ${esc(ownerText(source.owner))}</bdi><br><span aria-hidden="true">↓</span><br><bdi>${esc(accountTitle(target))} · ${esc(ownerText(target.owner))}</bdi></p><label class="check-field"><input id="same-holders" type="checkbox"><span>${t('sameHolders')}</span></label><div class="button-row">${button('link-account','linkAccount','primary','disabled')}</div>`);$('#same-holders').onchange=e=>$('#link-account').disabled=!e.target.checked;$('#link-account').onclick=()=>{source.linkedDematId=targetId;source.familyReviewedOn='';if(unfinished?.sourceId===sourceId)unfinished.sourceId='';source.events=[...source.events,{kind:'linked',on:today()}].slice(-20);markDirty();selected=targetId;d.close();go('detail');};}
function foldCalendar(value){const encoder=new TextEncoder();return value.split('\r\n').map(line=>{let part='',size=0,folded='';for(const char of line){const bytes=encoder.encode(char).length;if(size+bytes>73){folded+=part+'\r\n ';part='';size=1;}part+=char;size+=bytes;}return folded+part;}).join('\r\n');}
function calendarFile(){const a=account(),dateString=a.followupOn.replaceAll('-',''),stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');download(foldCalendar(`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Virasat//Follow-up//EN\r\nBEGIN:VEVENT\r\nUID:${a.id}-${dateString}@virasat.local\r\nDTSTAMP:${stamp}\r\nDTSTART;VALUE=DATE:${dateString}\r\nSUMMARY:Virasat - review nomination record\r\nDESCRIPTION:Open your saved Virasat list to review the next step. No private account details are included.\r\nBEGIN:VALARM\r\nTRIGGER:-PT9H\r\nACTION:DISPLAY\r\nDESCRIPTION:Review your Virasat list\r\nEND:VALARM\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n`),'virasat-follow-up.ics','text/calendar');}
function readableFile(){const body=sheetBody().replace(/ data-speak/g,'');download(`<!doctype html><html lang="${lang}"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(t('summary'))}</title><style>body{font:17px/1.7 system-ui,sans-serif;max-width:760px;margin:40px auto;padding:0 24px;color:#282522}article{padding:20px 0;border-bottom:1px solid #ccc}h1,h2{line-height:1.35}p{margin:8px 0}a{color:#85432f}.micro{font-size:14px}.status-pill{font-size:14px}bdi{unicode-bidi:isolate}</style><body ${lang==='ur'?'dir="rtl"':''}><h1>${esc(t('summary'))}</h1><p>${date(today())}</p>${body}</body></html>`,'virasat-family-summary.html','text/html');}
function returnFromVault(){if(returnView==='form'&&editorMode==='new'&&unfinished){draft=structuredClone(unfinished.account);step=unfinished.step;pendingDematSource=unfinished.sourceId||'';editorMode='new';view='form';draw();return;}if(pendingEditor&&returnView===pendingEditor.view){selected=pendingEditor.account.id;draft=structuredClone(pendingEditor.account);step=pendingEditor.step;editorMode=pendingEditor.mode;view=pendingEditor.view;draw();return;}go(['save','resume','form','family','confirm','submit','followup'].includes(returnView)?'home':returnView);}
function saveView(){generation++;keepDraft();returnView=view;draft=null;view='save';draw();}
async function handleVault(form){
 clearErrors();const password=$('#password').value,saving=view==='save',run=generation;
 if(password.length<12||password.length>256){showError('password-error','passwordShort');$('#password').focus();return;}
 if(saving&&password!==$('#password-repeat').value){showError('password-repeat-error','passwordMismatch');$('#password-repeat').focus();return;}
 const submit=form.querySelector('[type=submit]');submit.disabled=true;$('#vault-status').textContent=t('saving');
 try{
  if(saving){const payload=saveWorkspace(current,unfinished,pendingEditor,lang);const sealed=await sealCase(payload,password);if(run!==generation||view!=='save')return;
   const keep=$('#keep-device').checked;let storageFailed=false;if(keep){try{localStorage.setItem(deviceKey,sealed);deviceCopy=true;}catch{storageFailed=true;}}
   download(sealed,`virasat-${today()}.virasat`);dirty=false;savedFile=true;$('#vault-status').textContent=t(storageFailed?'deviceUnavailable':'saved');$('#password').value='';$('#password-repeat').value='';const next=document.createElement('div');next.className='save-complete';next.innerHTML=copy('savedNext')+(!keep&&deviceCopy?copy('olderDeviceCopy','p','help'):'')+button('return-after-save','returnTask','primary');form.querySelector('.save-complete')?.remove();form.append(next);next.querySelector('button').focus();
  }else{let encrypted;const file=$('#saved-file').files[0];if($('#use-device')?.checked){encrypted=localStorage.getItem(deviceKey);if(!encrypted)throw new Error('invalidSave');}else{if(!file){showError('saved-file-error','chooseFile');$('#saved-file').focus();return;}if(file.size>2*1024*1024)throw new Error('invalidSave');encrypted=await file.text();}
   const restored=restoreWorkspace(await openCase(encrypted,password));if(run!==generation||view!=='resume')return;current=restored.tracker;pendingEditor=restored.editor;unfinished=restored.draft?{account:restored.draft,step:restored.step,sourceId:restored.linkFrom}:null;pendingDematSource=restored.linkFrom;lang=restored.language||lang;dirty=false;savedFile=true;draft=null;view='home';generation++;draw();announce('restored');
  }
 }catch(error){if(view===(saving?'save':'resume'))$('#vault-status').textContent=t(['passwordShort','invalidSave','cannotUnlock','invalidAccount','invalidDate'].includes(error.message)?error.message:'cannotUnlock');}
 finally{if(submit.isConnected)submit.disabled=false;}
}
main.addEventListener('input',e=>{
 const el=e.target;if(!draft)return;
 if(el.dataset.dateName){dateParts(el.dataset.dateName)[el.dataset.datePart]=normaliseDigits(el.value).replace(/[^0-9]/g,'');el.value=dateParts(el.dataset.dateName)[el.dataset.datePart];}
 else if(el.dataset.nominee!==undefined){draft.nominees[Number(el.dataset.nominee)]=el.value;}
 else if(el.name&&Object.hasOwn(draft,el.name)){const before=draft[el.name];draft[el.name]=el.type==='checkbox'?el.checked:el.name==='last4'?normaliseDigits(el.value):el.value;if(el.name==='type'&&before!==el.value){draft.institution='';draft.institutionId='';if(el.value!=='demat')pendingDematSource='';}}
 if(view==='family'){if(el.id==='reviewed-family')draft.familyReviewedOn=el.checked?today():'';else{draft.familyReviewedOn='';$('#reviewed-family').checked=false;}}
 if(el.id==='choose-optout'){draft.nomination=el.checked?'optout':'unknown';main.querySelectorAll('[name=nomination]').forEach(r=>r.checked=r.value===draft.nomination);}
 if(el.name==='nomination')$('#choose-optout').checked=false;
 markDirty();
});
main.addEventListener('change',e=>{if(e.target.id==='saved-file'&&$('#use-device'))$('#use-device').checked=false;if(e.target.id==='use-device'&&e.target.checked)$('#saved-file').value='';if(e.target.id==='show-password')main.querySelectorAll('#password,#password-repeat').forEach(el=>el.type=e.target.checked?'text':'password');if(e.target.id==='share-names'||e.target.id==='share-location'){shareNames=$('#share-names').checked;shareLocation=$('#share-location').checked;$('#family-sheet').innerHTML=sheetBody();pageDirection();}});
main.addEventListener('submit',async e=>{
 e.preventDefault();const id=e.target.id;clearErrors();
 if(id==='vault-form'){await handleVault(e.target);return;}
 if(id==='account-form'){
  if(!draft.type){showError('type-error','chooseType');$('[name=type]')?.focus();return;}
  if((editorMode==='edit'||step===1)&&!draft.institution.trim()){invalid('institution','requiredInstitution');return;}
  if(editorMode==='new'&&step<3){step++;draw();return;}
  try{if(editorMode==='edit'){if(draft.mfMode!=='demat')draft.linkedDematId='';const old=account();if(['institution','type','owner','holding','product','mfMode'].some(k=>old[k]!==draft[k])){draft.linkedDematId='';draft=transition(draft,'recheck');for(const linked of current.accounts)if(linked.linkedDematId===old.id){linked.linkedDematId='';linked.familyReviewedOn='';}}}storeAccount(draft);}catch(err){showError('form-error',t(err.message)===err.message?'invalidSave':err.message);}return;
 }
 if(id==='family-form'){if(draft.last4&&!/^\d{4}$/.test(draft.last4)){invalid('last4','invalidAccount');return;}try{storeAccount(draft);}catch(err){showError('form-error',t(err.message)===err.message?'invalidSave':err.message);}return;}
 if(id==='progress-form'){
  if(view==='confirm'&&!draft.recordKind){invalid('recordKind','requiredRecord');return;}
  readDates();const key=view==='confirm'?'confirmationOn':view==='submit'?'submittedOn':'followupOn';
  const parts=draft._dateParts?.[key];const partial=parts&&Object.values(parts).some(Boolean)&&(!/^\d{4}$/.test(parts.year)||!/^\d{1,2}$/.test(parts.month)||!/^\d{1,2}$/.test(parts.day));
  if(partial||view!=='followup'&&!draft[key]||!validDate(draft[key],view==='followup')||view==='confirm'&&draft.submittedOn&&draft.confirmationOn<draft.submittedOn){invalid(key,view==='followup'?'validFollowup':'invalidDate');return;}
  if(view==='confirm'&&!draft.confirmationChecked){invalid('confirmationChecked','requiredCheck');return;}
  try{storeAccount(view==='followup'?draft:transition(draft,view==='confirm'?'confirmed':'submitted'));}catch(err){showError('form-error',t(err.message)===err.message?'invalidSave':err.message);}
 }
});
main.addEventListener('click',async e=>{
 const target=e.target.closest('button,a');if(!target)return;
 if(target.dataset.language){lang=target.dataset.language;chosen=true;draw();return;}
 if(target.dataset.account){selected=target.dataset.account;go('detail');return;}
 if(target.dataset.removeNominee!==undefined){draft.nominees.splice(Number(target.dataset.removeNominee),1);draft.familyReviewedOn='';markDirty();draw(false);$('#add-nominee')?.focus();return;}
 const id=target.id;
 if(id==='listen'){readPage();return;}if(id==='speech-pause'){reader.state==='paused'?reader.resume():reader.pause();return;}if(id==='speech-stop'){reader.stop();return;}if(id==='speech-help'){accessDialog();return;}if(id==='speech-previous'){reader.previous();return;}if(id==='speech-repeat'){reader.repeat();return;}if(id==='speech-next'){reader.next();return;}
 if(id==='add'){if(current.synthetic){confirmAction('startOwnHelp',()=>{current=emptyTracker();unfinished=null;pendingEditor=null;begin();});return;}if(unfinished)confirmAction('replaceDraft',begin);else begin();}
 if(id==='demo'){const action=()=>{current=sampleTracker();unfinished=null;pendingEditor=null;markDirty();go('home');};current.accounts.length||unfinished?confirmAction('replaceList',action):action();}
 if(id==='continue-editor'){draft=structuredClone(pendingEditor.account);selected=draft.id;step=pendingEditor.step;editorMode=pendingEditor.mode;view=pendingEditor.view;draw();}
 if(id==='continue-draft'){pendingDematSource=unfinished.sourceId||'';draft=structuredClone(unfinished.account);step=unfinished.step;editorMode='new';view='form';draw();}
 if(['back-list','cancel-edit'].includes(id))go('home');
 if(['back-detail','cancel-progress','cancel-family'].includes(id)){keepDraft();draft=null;go('detail');}
 if(id==='form-back'){if(editorMode==='new'&&step>0){step--;draw();}else go(editorMode==='edit'?'detail':'home');}
 if(['summary','prepare','check-result'].includes(id)){if(id==='prepare')routeMode='online';go(id==='check-result'?'check':id);}
 if(id==='route-online'||id==='route-offline'){routeMode=id==='route-offline'?'offline':'online';draw(false);document.getElementById(id).focus();}
 if(id==='edit-account')openEditor('form');
 if(['family','family-aside'].includes(id))openEditor('family');
 if(id==='add-nominee'){draft.familyReviewedOn='';if(!draft.nominees.length)draft.nominees.push('');draft.nominees.push('');markDirty();draw(false);$('#nominee-'+(draft.nominees.length-1))?.focus();}
 if(['confirm-record','found-yes'].includes(id))openProgress('confirm');
 if(id==='submit-request')openProgress('submit');
 if(id==='followup')openProgress('followup');
 const moves={'found-no':'missing','found-change':'change','found-unknown':'unknown','found-optout':'optout',blocked:'blocked',recheck:'recheck','change-nomination':'change'};
 if(moves[id])storeAccount(transition(account(),moves[id]));
 if(id==='use-demat'){if(account().linkedDematId){selected=account().linkedDematId;go('detail');return;}const sourceId=selected;const candidates=current.accounts.filter(a=>a.type==='demat');if(candidates.length){const d=openDialog('confirm-dialog',`${dialogHead('confirm-title','useDemat')}${copy('mfDematHelp')}<div class="answer-list">${candidates.map(a=>`<button type="button" class="answer-button" data-link-demat="${a.id}">${esc(accountTitle(a))} · ${esc(ownerText(a.owner))}</button>`).join('')}${button('new-demat','add','secondary')}</div>`);d.querySelectorAll('[data-link-demat]').forEach(b=>b.onclick=()=>{const targetId=b.dataset.linkDemat;d.close();confirmDematLink(sourceId,targetId);});$('#new-demat').onclick=()=>{d.close();beginLinkedDemat(sourceId);};}else beginLinkedDemat(sourceId);}
 if(id==='remove-account')confirmAction('removeAsk',()=>{if(pendingEditor?.account.id===selected)pendingEditor=null;if(unfinished?.sourceId===selected)unfinished.sourceId='';if(pendingDematSource===selected)pendingDematSource='';current.accounts=current.accounts.filter(a=>a.id!==selected);for(const a of current.accounts)if(a.linkedDematId===selected)a.linkedDematId='';markDirty();go('home');});
 if(['save-notice','save-sheet','route-save'].includes(id))saveView();
 if(id==='resume'){const action=()=>{returnView='home';go('resume');};dirty&&(current.accounts.length||unfinished)?confirmAction('replaceList',action):action();}
 if(id==='back-vault'||id==='return-after-save')returnFromVault();
 if(id==='forget-device')confirmAction('forgetDeviceAsk',()=>{try{localStorage.removeItem(deviceKey);deviceCopy=false;draw();}catch{announce('deviceUnavailable');}});
 if(id==='print')window.print();if(id==='export')readableFile();if(id==='calendar')calendarFile();
 if(id==='copy-question'){try{await navigator.clipboard.writeText(t('askText'));target.textContent=t('copied');}catch{const range=document.createRange();range.selectNodeContents(target.previousElementSibling);const sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);}}
});
$('#home-button').onclick=()=>go('home');$('.brand').onclick=e=>{e.preventDefault();go('home');};$('#language-button').onclick=languageDialog;$('#access-toggle').onclick=accessDialog;$('#help').onclick=helpDialog;
$('#clear').onclick=()=>confirmAction('clearAsk',()=>{generation++;current=emptyTracker();unfinished=null;pendingEditor=null;pendingDematSource='';draft=null;dirty=false;savedFile=false;go('home');announce('clearDone');});
for(const d of document.querySelectorAll('dialog'))d.addEventListener('close',()=>{reader.stop();if(dialogOrigin?.isConnected)dialogOrigin.focus();});
window.addEventListener('beforeunload',e=>{if(dirty&&(current.accounts.length||draft||unfinished)){e.preventDefault();e.returnValue='';}});
window.addEventListener('pagehide',()=>reader.stop());
window.speechSynthesis?.addEventListener('voiceschanged',()=>{if($('#access-dialog').open){const active=document.activeElement?.id;$('#access-dialog').close();accessDialog();if(active&&document.getElementById(active))document.getElementById(active).focus();}});
draw(false);
